    #[test]
    fn level_entry_level_1_exposes_letters_on_local_frame_43_and_number_on_44() {
        let mut runtime = cached_generated_runtime();
        runtime.begin_level_entry(LevelId(0));

        let mut frame_41_slots = None;
        let mut frame_42_slots = None;
        let mut frame_43_slots = None;

        for frame_index in 0..=43 {
            let trace = runtime.step_frame(FrameInput::default());
            match frame_index {
                41 => {
                    frame_41_slots = Some(
                        trace
                            .active_objects
                            .iter()
                            .filter_map(|object| object.debug_fields.get("gfx_slot_index"))
                            .map(|slot| slot.parse::<usize>().expect("numeric gfx slot"))
                            .collect::<Vec<_>>(),
                    );
                }
                42 => {
                    frame_42_slots = Some(
                        trace
                            .active_objects
                            .iter()
                            .filter_map(|object| object.debug_fields.get("gfx_slot_index"))
                            .map(|slot| slot.parse::<usize>().expect("numeric gfx slot"))
                            .collect::<Vec<_>>(),
                    );
                }
                43 => {
                    frame_43_slots = Some(
                        trace
                            .active_objects
                            .iter()
                            .filter_map(|object| object.debug_fields.get("gfx_slot_index"))
                            .map(|slot| slot.parse::<usize>().expect("numeric gfx slot"))
                            .collect::<Vec<_>>(),
                    );
                }
                _ => {}
            }
        }

        let frame_41_slots = frame_41_slots.expect("frame 41 trace");
        let frame_42_slots = frame_42_slots.expect("frame 42 trace");
        let frame_43_slots = frame_43_slots.expect("frame 43 trace");

        // ASM Allocate_ObjectSlot / Delete_CurrentObject (kid.asm:1583-1616,
        // 1790-1794) insert the new loc_1AC70 workers ahead of the current
        // loc_1AB26 object, so that pass only updates the hidden object counts.
        // The next pass then exposes the 13 letter workers first, and the
        // deferred loc_1AD48 number worker joins one frame after that.
        // `step_frame()` increments the local `elapsed_frames` counter before
        // tracing, so those oracle-backed exposures land on traced frames 42/43
        // while corresponding to local animation frames 43/44.
        assert_eq!(frame_41_slots, Vec::<usize>::new());
        assert_eq!(frame_42_slots, (0..=12).collect::<Vec<_>>());
        assert_eq!(frame_43_slots, (0..=13).collect::<Vec<_>>());
    }

    #[test]
    fn level_entry_title_workers_seed_only_on_activation_frame_and_only_once() {
        let mut runtime = cached_generated_runtime();
        runtime.begin_level_entry(LevelId(0));
        runtime.starting_level_title_workers.truncate(1);

        let activation_frame = crate::movement::LEVEL_ENTRY_TITLE_FIRST_VISIBLE_TRACE_FRAME;
        runtime.maybe_seed_starting_level_title_workers(activation_frame - 1);
        assert!(
            runtime.starting_level_title_workers[0].motion.is_none(),
            "ASM loc_1AC70 should not run the random entry-pose seed before the worker reaches its title-card activation frame",
        );

        runtime.maybe_seed_starting_level_title_workers(activation_frame);
        let seeded_motion = runtime.starting_level_title_workers[0]
            .motion
            .clone()
            .expect("activation frame should seed the title-worker glide");
        assert_eq!(
            (seeded_motion.start_x_pos, seeded_motion.start_y_pos),
            (0xFFE0_0000, 0x0070_0000),
            "ASM loc_1ACB0 should mask the ROM RNG byte with `& 3`; the default stream's first selector is zero and enters from the left edge at random Y `$70`",
        );

        runtime.maybe_seed_starting_level_title_workers(activation_frame);
        assert_eq!(
            runtime.starting_level_title_workers[0].motion,
            Some(seeded_motion),
            "ASM loc_1AC70 seeds each title worker once; already-active workers should not consume a second random entry pose on the same frame",
        );
    }

