    /// ASM loc_FAE2 (kid.asm:20864): converts the caller's block column/row
    /// back into a `Level_Layout` word pointer through the `$FFFF4A04`
    /// row-pointer table before returning the address in `d3`.
    #[test]
    #[allow(non_snake_case)]
    fn loc_FAE2_resolves_block_coordinates_to_the_level_layout_word_address() {
        assert_eq!(
            crate::level::level_layout_word_address_loc_FAE2(0x0012, 0x0007, 0xFFFF_A652),
            crate::level::LayoutWordAddressLocFAE2 {
                row_pointer_table_byte_offset: 0x000E,
                layout_word_addr: 0xFFFF_A676,
            },
            "ASM loc_FAE2 should double the row for the row-pointer-table offset, then add `block_col * 2` bytes to the loaded row base",
        );
    }

    /// ASM loc_F8CA (kid.asm:20589): computes the remaining loop count from the
    /// source width table plus start column, restores every layout byte, and emits
    /// FG queue entries only for the visible span after the `-8..+camera_right`
    /// cull check.
    #[test]
    #[allow(non_snake_case)]
    fn loc_F8CA_restores_layout_and_emits_visible_horizontal_queue_entries() {
        let source_cells = (0u8..48).collect::<Vec<_>>();
        let mut theme_mappings = vec![[0x1111_1111, 0x2222_2222]; 0x100];
        theme_mappings[0x0A] = [0xA1A1_0001, 0xA1A1_0002];
        theme_mappings[0x0B] = [0xA1B1_0001, 0xA1B1_0002];
        theme_mappings[0x0C] = [0xA1C1_0001, 0xA1C1_0002];

        let rows = crate::level::animated_solid_block_horizontal_rows_loc_F8CA(
            &source_cells,
            0,
            4,
            8,
            0x0012,
            0x0400,
            10,
            12,
            0x000A,
            0x0015,
            &theme_mappings,
        );

        assert_eq!(
            rows.layout_writes,
            (8..=20)
                .map(|col| {
                    let col = col as u16;
                    (0x0400 + (u32::from(col - 8) * 2), col)
                })
                .collect::<Vec<_>>(),
            "ASM loc_F8CA should restore each source layout byte to `(a4)+` for the full loop length"
        );
        assert_eq!(
            rows.custom_queue_entries,
            vec![
                crate::level::FgUpdateQueueCustomEntrySub1596 {
                    vram_word_address: 0x0228,
                    first_longword: 0xA1A1_0001,
                    second_longword: 0xA1A1_0002,
                },
                crate::level::FgUpdateQueueCustomEntrySub1596 {
                    vram_word_address: 0x022C,
                    first_longword: 0xA1B1_0001,
                    second_longword: 0xA1B1_0002,
                },
                crate::level::FgUpdateQueueCustomEntrySub1596 {
                    vram_word_address: 0x0230,
                    first_longword: 0xA1C1_0001,
                    second_longword: 0xA1C1_0002,
                },
            ],
            "ASM loc_F8CA should only queue FG entries when the source column is visible after the pre-cull"
        );
        assert_eq!(
            rows.final_layout_addr,
            0x0400 + (u32::from((4u16 + 8 + 1) * 2)),
            "ASM loc_F934 should advance the layout queue pointer by one word per processed source byte"
        );
        assert_eq!(
            rows.final_col, 21,
            "ASM loc_F8CA should increment the source column each loop iteration"
        );
        assert_eq!(
            rows.remaining_count, 0xFFFF,
            "ASM loc_F934 should leave d3 at -1 after the terminal DBF decrement"
        );

        let row_above_window = crate::level::animated_solid_block_horizontal_rows_loc_F8CA(
            &[0x0A],
            0,
            0,
            0,
            0x0009,
            0x0500,
            0,
            0,
            0x000A,
            0x0015,
            &theme_mappings,
        );
        assert_eq!(
            row_above_window.layout_writes,
            vec![(0x0500, 0x000A)],
            "ASM loc_F93C should still restore layout bytes when loc_F8CA culls a row above the camera"
        );
        assert!(
            row_above_window.custom_queue_entries.is_empty(),
            "ASM loc_F8CA should branch to loc_F93C before loc_F90A when `cmp.w d5,d1; blt` rejects the row"
        );

        let start_at_left_minus_eight = crate::level::animated_solid_block_horizontal_rows_loc_F8CA(
            &source_cells,
            0,
            10,
            2,
            0x0012,
            0x0600,
            10,
            12,
            0x000A,
            0x0015,
            &theme_mappings,
        );
        assert!(
            start_at_left_minus_eight.custom_queue_entries.is_empty(),
            "ASM loc_F8CA should branch to loc_F93C for the whole span when `start_col-camera_left <= -8`, even if later columns reach the camera"
        );
    }

    /// ASM loc_F85A (kid.asm:20528): each DBF iteration writes `$E304` to the
    /// current Level_Layout cell, queues VDP data only for visible rows, then
    /// advances by one row through `Level_width_tiles`.
    #[test]
    #[allow(non_snake_case)]
    fn loc_F85A_writes_vertical_animated_block_rows_and_visible_queue_entries() {
        let rows = crate::level::animated_solid_block_vertical_rows_loc_F85A(
            crate::level::AnimatedSolidBlockVerticalRowsInputLocF85A {
                start_layout_addr: 0xFFFF_A652,
                start_row: 0x001F,
                dbf_row_counter: 3,
                level_width_tiles: 0x0050,
                camera_top_row: 0x0020,
                camera_bottom_row: 0x0021,
                packed_cell_x_bits: 0x0004,
                mapping_longwords: [0x1111_2222, 0x3333_4444],
            },
        );

        assert_eq!(
            rows.layout_writes,
            vec![
                (0xFFFF_A652, 0xE304),
                (0xFFFF_A6A2, 0xE304),
                (0xFFFF_A6F2, 0xE304),
                (0xFFFF_A742, 0xE304),
            ],
            "ASM loc_F85A should write `$E304` before each visibility check and advance a4 by Level_width_tiles"
        );
        assert_eq!(
            rows.custom_queue_entries,
            vec![
                crate::level::FgUpdateQueueCustomEntrySub1596 {
                    vram_word_address: 0x0004,
                    first_longword: 0x1111_2222,
                    second_longword: 0x3333_4444,
                },
                crate::level::FgUpdateQueueCustomEntrySub1596 {
                    vram_word_address: 0x0104,
                    first_longword: 0x1111_2222,
                    second_longword: 0x3333_4444,
                },
            ],
            "ASM loc_F85A should queue only rows within the inclusive camera Y window using `((row << 8) & $F00) | packed_x`"
        );
        assert_eq!(rows.final_row, 0x0023);
        assert_eq!(rows.final_layout_addr, 0xFFFF_A792);
    }

    /// ASM loc_EAC6 (kid.asm:18839): `sub_EABC` seeds `a0=$FFFFEBDA` and
    /// `d0=$26`, then the inclusive DBF loop links each `$0C`-byte evanescent
    /// slot to the next before clearing the final `$A(a0)` word.
    #[test]
    #[allow(non_snake_case)]
    fn loc_EAC6_links_the_sub_EABC_evanescent_free_list_until_dbf_exits() {
        let slots = crate::level::initialise_evanesc_object_slots_sub_EABC();

        assert_eq!(
            slots.evanescent_slots.len(),
            0x28,
            "ASM loc_EAC6 starts with d0=$26, so the inclusive DBF loop writes links for 39 slots plus one terminal slot"
        );
        assert_eq!(
            slots.evanescent_slots[0],
            crate::level::LinkedObjectSlotInit {
                slot_addr: 0xFFFF_EBDA,
                next_slot_addr: 0xFFFF_EBE6,
            },
            "ASM loc_EAC6 should write `$A(a0)=a0+$0C` before advancing a0"
        );
        assert_eq!(
            slots.evanescent_slots[0x27],
            crate::level::LinkedObjectSlotInit {
                slot_addr: 0xFFFF_EDAE,
                next_slot_addr: 0,
            },
            "ASM loc_EAC6 should clear `$A(a0)` only after DBF falls through from the last linked slot"
        );
    }

    /// ASM loc_E07A (kid.asm:17395): load the hidden/prize block metadata base
    /// from `$FFFFF8D4`, preserve the current layout word pointer in `d4`, and
    /// bias `a0` by `-8` before the pre-increment scan.
    #[test]
    #[allow(non_snake_case)]
    fn loc_E07A_hidden_block_evanescent_scan_biases_cursor_before_first_record() {
        let scan = crate::level::hidden_block_evanescent_scan_start_loc_E07A(0x0001_2400, 0x03A6);

        assert_eq!(
            scan.preincrement_cursor_addr, 0x0001_23F8,
            "ASM loc_E07A should subtract 8 from the metadata cursor before the next scan adds 8"
        );
        assert_eq!(
            scan.first_record_addr, 0x0001_2400,
            "ASM loc_E07A should make the first scan add land on the first 8-byte metadata record"
        );
        assert_eq!(
            scan.layout_word_addr, 0x03A6,
            "ASM loc_E07A should compare records against the current layout word pointer copied from a2"
        );
    }

    /// ASM loc_E082 (kid.asm:17400): add 8 to the metadata cursor until the
    /// record layout word matches `d4`, then use the signed word at offset 6 to
    /// decide whether evanescent reveal sprite words replace the default.
    #[test]
    #[allow(non_snake_case)]
    fn loc_E082_hidden_block_evanescent_scan_uses_8_byte_records_and_negative_gate() {
        let records = [
            crate::level::HiddenBlockMetadataRecordLocE082 {
                layout_word_addr: 0x0100,
                control_word: 0,
            },
            crate::level::HiddenBlockMetadataRecordLocE082 {
                layout_word_addr: 0x0120,
                control_word: 0x0001,
            },
            crate::level::HiddenBlockMetadataRecordLocE082 {
                layout_word_addr: 0x0140,
                control_word: -1,
            },
        ];

        let matched = crate::level::hidden_block_evanescent_metadata_scan_loc_E082(
            0x0001_2400,
            0x0140,
            &records,
        )
        .expect("ASM loc_E082 should scan until the matching layout word is found");

        assert_eq!(
            matched.matched_record_addr, 0x0001_2410,
            "ASM loc_E082 should advance by one 8-byte metadata record per failed comparison"
        );
        assert_eq!(
            matched.scanned_records, 3,
            "ASM loc_E082 should include the matching record in the scan count"
        );
        assert_eq!(
            matched.evanescent_sprite_words,
            Some((0xE101, 0x1058)),
            "ASM loc_E082 should replace the reveal sprite words only when `tst.w 6(a0)` is negative"
        );

        let ordinary = crate::level::hidden_block_evanescent_metadata_scan_loc_E082(
            0x0001_2400,
            0x0120,
            &records,
        )
        .expect("ASM loc_E082 should also return ordinary matching records");
        assert_eq!(
            ordinary.evanescent_sprite_words, None,
            "ASM loc_E082 should leave existing reveal sprite words unchanged for non-negative control words"
        );
    }

    /// ASM loc_E096 (kid.asm:17409): reveal the hidden block cell and allocate
    /// the single debris/animation object that carries the selected sprite
    /// words plus the block position and layout pointer.
    #[test]
    #[allow(non_snake_case)]
    fn loc_E096_hidden_block_reveal_allocates_single_worker_with_selected_sprite_words() {
        let worker = crate::level::hidden_block_reveal_worker_loc_E096(
            0x0012,
            0x0007,
            0x0000_03A6,
            0xE101,
            0x1058,
        );

        assert_eq!(
            worker.revealed_layout_byte, 0x60,
            "ASM loc_E096 should write `$60` to the hidden block layout byte before allocating the worker"
        );
        assert_eq!(
            worker.allocation_spec, 0x2001,
            "ASM loc_E096 should allocate an object slot with a0=`$2001`"
        );
        assert_eq!(
            worker.object_handler_addr, 0x0000_E29A,
            "ASM loc_E096 should install the reveal worker handler at `$E29A`"
        );
        assert_eq!(
            (worker.block_col, worker.block_row, worker.layout_word_addr),
            (0x0012, 0x0007, 0x0000_03A6),
            "ASM loc_E096 should copy d0/d6/a2 into object fields `$44/$46/$48`"
        );
        assert_eq!(
            (worker.sprite_tile_word, worker.sprite_mapping),
            (0xE101, 0x1058),
            "ASM loc_E096 should copy d2/d3 into object fields `$4C/$4E` without altering them"
        );
    }

    /// ASM loc_E48E (kid.asm:17988): the prize-reveal scan tail always
    /// advances `d5/a2`, then DBF loops back to `sub_E446` until `d6` reaches
    /// `$FFFF` after decrement.
    #[test]
    #[allow(non_snake_case)]
    fn loc_E48E_hidden_block_prize_reveal_scan_tail_advances_rows_until_dbf_exits() {
        let continuing =
            crate::level::hidden_block_prize_reveal_scan_tail_loc_E48E(0x0012, 0x03A6, 0x00F0, 2);
        assert_eq!(
            continuing.next_block_col, 0x0013,
            "ASM loc_E48E should addq.w #1,d5 before the DBF test"
        );
        assert_eq!(
            continuing.next_layout_word_addr, 0x0496,
            "ASM loc_E48E should add Level_width_tiles to a2 without scaling it again"
        );
        assert_eq!(
            continuing.next_dbf_counter, 1,
            "ASM loc_E48E should DBF-decrement the scan counter after advancing the cursor"
        );
        assert!(
            continuing.loops_to_sub_e446,
            "ASM loc_E48E should branch back to sub_E446 while the DBF counter is not `$FFFF`"
        );

        let terminal =
            crate::level::hidden_block_prize_reveal_scan_tail_loc_E48E(0xFFFF, 0xFFF0, 0x0020, 0);
        assert_eq!(
            terminal.next_block_col, 0,
            "ASM loc_E48E uses word arithmetic, so d5 wraps on addq.w"
        );
        assert_eq!(
            terminal.next_layout_word_addr, 0x0010,
            "ASM loc_E48E uses word arithmetic when adding Level_width_tiles into a2"
        );
        assert!(
            !terminal.loops_to_sub_e446,
            "ASM loc_E48E should return once DBF decrements zero to `$FFFF`"
        );
    }

    /// ASM loc_EA3E (kid.asm:18770): decrement `$8(a2)` first. Only a timer
    /// of one is restored to one and allowed to test the signed layout byte's
    /// low nibble before falling through to `loc_EA5A`.
    #[test]
    #[allow(non_snake_case)]
    fn loc_EA3E_evanescent_removal_gate_requires_timer_and_negative_low_nibble() {
        let waiting = crate::level::evanescent_block_removal_gate_loc_EA3E(3, 0x8C);
        assert_eq!(
            waiting,
            crate::level::EvanescentBlockRemovalGateLocEA3E {
                next_timer: 2,
                should_try_remove_block: false,
            },
            "ASM loc_EA3E should branch to loc_EAAA after any non-zero post-decrement timer"
        );

        let wrapped = crate::level::evanescent_block_removal_gate_loc_EA3E(0, 0x8C);
        assert_eq!(
            wrapped.next_timer, 0xFFFF,
            "ASM loc_EA3E should use word wrapping before the BNE test"
        );
        assert!(
            !wrapped.should_try_remove_block,
            "ASM loc_EA3E should not inspect the layout byte when the wrapped timer is non-zero"
        );

        let solid = crate::level::evanescent_block_removal_gate_loc_EA3E(1, 0x8C);
        assert_eq!(
            solid,
            crate::level::EvanescentBlockRemovalGateLocEA3E {
                next_timer: 1,
                should_try_remove_block: true,
            },
            "ASM loc_EA3E should restore the timer to one and continue only for negative layout bytes with low nibble < `$D`"
        );

        assert!(
            !crate::level::evanescent_block_removal_gate_loc_EA3E(1, 0x7C).should_try_remove_block,
            "ASM loc_EA3E should branch away when `move.b (a1),d0` is non-negative"
        );
        assert!(
            !crate::level::evanescent_block_removal_gate_loc_EA3E(1, 0x00).should_try_remove_block,
            "ASM loc_EA3E should treat zero as non-negative, so `bpl.s loc_EAAA` must fire"
        );
        assert!(
            !crate::level::evanescent_block_removal_gate_loc_EA3E(1, 0x8D).should_try_remove_block,
            "ASM loc_EA3E should branch away when the low nibble is `$D` or higher"
        );
    }

    /// ASM loc_EA5A (kid.asm:18783): only an exact word match between `(a1)`
    /// and `$6(a2)` calls `EraseBlockFromLevelLayout`; after that call the ROM
    /// overwrites the high byte of the updated cell with `$20`.
    #[test]
    #[allow(non_snake_case)]
    fn loc_EA5A_erases_only_the_saved_cell_word_match() {
        let matched = crate::level::evanescent_block_erase_match_loc_EA5A(
            0x8C34, 0x8C34, 0x0012, 0x0007, 0x6A5B,
        );

        assert_eq!(
            matched,
            crate::level::EvanescentBlockEraseMatchLocEA5A {
                should_erase_block_from_level_layout: true,
                erased_block_col: Some(0x0012),
                erased_block_row: Some(0x0007),
                final_layout_cell_word: 0x205B,
            },
            "ASM loc_EA5A should pass `$2(a2)/$4(a2)` to EraseBlockFromLevelLayout and then force byte `$20` over the erased cell high byte"
        );

        let mismatched = crate::level::evanescent_block_erase_match_loc_EA5A(
            0x8C35, 0x8C34, 0x0012, 0x0007, 0x6A5B,
        );
        assert_eq!(
            mismatched,
            crate::level::EvanescentBlockEraseMatchLocEA5A {
                should_erase_block_from_level_layout: false,
                erased_block_col: None,
                erased_block_row: None,
                final_layout_cell_word: 0x8C35,
            },
            "ASM loc_EA5A should skip EraseBlockFromLevelLayout when another system has already changed the layout word"
        );
    }

    /// ASM loc_EA72 (kid.asm:18792): save `$A(a2)` before mutating links,
    /// unlink the current evanescent object from the active list, push it to
    /// the free-list head, then continue active processing from the saved link.
    #[test]
    #[allow(non_snake_case)]
    fn loc_EA72_moves_current_evanescent_slot_from_active_to_free_list() {
        let active_slots = [
            crate::level::LinkedObjectSlotInit {
                slot_addr: 0xFFFF_EBDA,
                next_slot_addr: 0xFFFF_EBE6,
            },
            crate::level::LinkedObjectSlotInit {
                slot_addr: 0xFFFF_EBE6,
                next_slot_addr: 0xFFFF_EBF2,
            },
            crate::level::LinkedObjectSlotInit {
                slot_addr: 0xFFFF_EBF2,
                next_slot_addr: 0,
            },
        ];

        let middle = crate::level::evanescent_object_move_active_to_free_loc_EA72(
            &active_slots,
            0xFFFF_EBE6,
            0xFFFF_EC10,
        )
        .expect("ASM loc_EA72 should find the current evanescent object in the active list");
        assert_eq!(
            middle,
            crate::level::EvanescentObjectListMoveLocEA72 {
                first_active_slot_addr: 0xFFFF_EBDA,
                first_free_slot_addr: 0xFFFF_EBE6,
                next_active_slot_to_process_addr: 0xFFFF_EBF2,
                slots: vec![
                    crate::level::LinkedObjectSlotInit {
                        slot_addr: 0xFFFF_EBDA,
                        next_slot_addr: 0xFFFF_EBF2,
                    },
                    crate::level::LinkedObjectSlotInit {
                        slot_addr: 0xFFFF_EBE6,
                        next_slot_addr: 0xFFFF_EC10,
                    },
                    crate::level::LinkedObjectSlotInit {
                        slot_addr: 0xFFFF_EBF2,
                        next_slot_addr: 0,
                    },
                ],
            },
            "ASM loc_EA72 should splice the predecessor over a middle slot, then make the removed slot point at the old free-list head"
        );

        let head = crate::level::evanescent_object_move_active_to_free_loc_EA72(
            &active_slots,
            0xFFFF_EBDA,
            0xFFFF_EC10,
        )
        .expect("ASM loc_EA72 should handle removal of Addr_FirstEvanescObjectSlot");
        assert_eq!(
            head.first_active_slot_addr, 0xFFFF_EBE6,
            "ASM loc_EA72 should update Addr_FirstEvanescObjectSlot from `$A(a2)` when the head slot is removed"
        );
        assert_eq!(
            head.next_active_slot_to_process_addr, 0xFFFF_EBE6,
            "ASM loc_EA72 should continue from the saved old `$A(a2)` link after pushing the removed head to the free list"
        );
        assert_eq!(
            head.slots[0].next_slot_addr, 0xFFFF_EC10,
            "ASM loc_EA72 should store Addr_NextFreeEvanescObjectSlot into `$A(a2)` before making `a2` the free-list head"
        );
    }

    /// ASM loc_EA86 (kid.asm:18801): for non-head removals, walk `$A(a0)`
    /// links from `Addr_FirstEvanescObjectSlot` until the next link equals the
    /// removed evanescent object in `a2`.
    #[test]
    #[allow(non_snake_case)]
    fn loc_EA86_finds_evanescent_active_list_predecessor() {
        let active_slots = [
            crate::level::LinkedObjectSlotInit {
                slot_addr: 0xFFFF_EBDA,
                next_slot_addr: 0xFFFF_EBF2,
            },
            crate::level::LinkedObjectSlotInit {
                slot_addr: 0xFFFF_EBE6,
                next_slot_addr: 0,
            },
            crate::level::LinkedObjectSlotInit {
                slot_addr: 0xFFFF_EBF2,
                next_slot_addr: 0xFFFF_EBE6,
            },
        ];

        assert_eq!(
            crate::level::evanescent_object_predecessor_scan_loc_EA86(&active_slots, 0xFFFF_EBE6,),
            Some(crate::level::EvanescentObjectPredecessorLocEA86 {
                predecessor_slot_addr: 0xFFFF_EBF2,
                scanned_links: 2,
            }),
            "ASM loc_EA86 should follow linked `$A` order, not physical slot order, until `$A(a0)` equals `a2`"
        );
        assert_eq!(
            crate::level::evanescent_object_predecessor_scan_loc_EA86(&active_slots, 0xFFFF_EC10,),
            None,
            "ASM loc_EA86 has no splice target when the active list reaches a null `$A` link first"
        );
    }

    /// ASM loc_EA92 (kid.asm:18809): the predecessor found in `a0` receives
    /// the removed evanescent object's saved `$A(a2)` successor.
    #[test]
    #[allow(non_snake_case)]
    fn loc_EA92_splices_predecessor_over_removed_evanescent_slot() {
        let active_slots = [
            crate::level::LinkedObjectSlotInit {
                slot_addr: 0xFFFF_EBDA,
                next_slot_addr: 0xFFFF_EBE6,
            },
            crate::level::LinkedObjectSlotInit {
                slot_addr: 0xFFFF_EBE6,
                next_slot_addr: 0xFFFF_EBF2,
            },
            crate::level::LinkedObjectSlotInit {
                slot_addr: 0xFFFF_EBF2,
                next_slot_addr: 0,
            },
        ];

        let spliced = crate::level::evanescent_object_splice_predecessor_loc_EA92(
            &active_slots,
            0xFFFF_EBDA,
            0xFFFF_EBE6,
        )
        .expect("ASM loc_EA92 should have both predecessor and target slots");

        assert_eq!(
            spliced,
            crate::level::EvanescentObjectSpliceLocEA92 {
                slots: vec![
                    crate::level::LinkedObjectSlotInit {
                        slot_addr: 0xFFFF_EBDA,
                        next_slot_addr: 0xFFFF_EBF2,
                    },
                    crate::level::LinkedObjectSlotInit {
                        slot_addr: 0xFFFF_EBE6,
                        next_slot_addr: 0xFFFF_EBF2,
                    },
                    crate::level::LinkedObjectSlotInit {
                        slot_addr: 0xFFFF_EBF2,
                        next_slot_addr: 0,
                    },
                ],
            },
            "ASM loc_EA92 should only copy `$A(a2)` into `$A(a0)`; the removed slot keeps its old link until the free-list push"
        );
    }

    /// ASM loc_EA98 (kid.asm:18812): push `a2` onto the evanescent free list,
    /// then use the previously saved `d0` link to decide whether active-list
    /// processing continues.
    #[test]
    #[allow(non_snake_case)]
    fn loc_EA98_pushes_removed_evanescent_slot_to_free_list() {
        let active_slots = [
            crate::level::LinkedObjectSlotInit {
                slot_addr: 0xFFFF_EBDA,
                next_slot_addr: 0xFFFF_EBF2,
            },
            crate::level::LinkedObjectSlotInit {
                slot_addr: 0xFFFF_EBE6,
                next_slot_addr: 0xFFFF_EBF2,
            },
            crate::level::LinkedObjectSlotInit {
                slot_addr: 0xFFFF_EBF2,
                next_slot_addr: 0,
            },
        ];

        let pushed = crate::level::evanescent_object_push_free_list_loc_EA98(
            &active_slots,
            0xFFFF_EBE6,
            0xFFFF_EC10,
            0xFFFF_EBF2,
        )
        .expect("ASM loc_EA98 should update the removed slot before making it the free-list head");

        assert_eq!(
            pushed,
            crate::level::EvanescentObjectFreeListPushLocEA98 {
                first_free_slot_addr: 0xFFFF_EBE6,
                should_continue_active_scan: true,
                next_active_slot_to_process_addr: 0xFFFF_EBF2,
                slots: vec![
                    crate::level::LinkedObjectSlotInit {
                        slot_addr: 0xFFFF_EBDA,
                        next_slot_addr: 0xFFFF_EBF2,
                    },
                    crate::level::LinkedObjectSlotInit {
                        slot_addr: 0xFFFF_EBE6,
                        next_slot_addr: 0xFFFF_EC10,
                    },
                    crate::level::LinkedObjectSlotInit {
                        slot_addr: 0xFFFF_EBF2,
                        next_slot_addr: 0,
                    },
                ],
            },
            "ASM loc_EA98 should write the old free-list head into `$A(a2)`, make `a2` the free-list head, and keep scanning when saved `d0` is non-zero"
        );

        let terminal = crate::level::evanescent_object_push_free_list_loc_EA98(
            &active_slots,
            0xFFFF_EBF2,
            0xFFFF_EC10,
            0,
        )
        .expect("ASM loc_EA98 should also push the terminal active slot");
        assert!(
            !terminal.should_continue_active_scan,
            "ASM loc_EA98 should stop active-list processing when saved `d0` is zero"
        );
    }

    /// ASM loc_EAB2 (kid.asm:18824): after the active-list scan ends, the ROM
    /// stores the current `a3` sprite cursor and low `d3` count byte back to
    /// the shared sprite globals.
    #[test]
    #[allow(non_snake_case)]
    fn loc_EAB2_returns_the_final_evanescent_sprite_cursor_and_count() {
        assert_eq!(
            crate::level::evanescent_sprite_scan_return_loc_EAB2(0xFFFF_0128, 0x25),
            crate::level::EvanescentSpriteScanReturnLocEAB2 {
                next_sprite_slot_addr: 0xFFFF_0128,
                number_sprites: 0x25,
            },
            "ASM loc_EAB2 should copy `a3` to Addr_NextSpriteSlot and `d3` to Number_Sprites without adjusting either value"
        );
    }

    /// ASM loc_EAE4 (kid.asm:18858): the scan expands Kid's hitbox by one
    /// pixel, clamps those expanded bounds to the level, converts them to
    /// inclusive tile counters, and only treats bit-15 block type `$A` cells as
    /// evanescent bullet-loader hits.
    #[test]
    #[allow(non_snake_case)]
    fn loc_EAE4_expands_the_kid_hitbox_window_and_detects_evanescent_blocks() {
        let mut data = vec![0; 4 * 4 * 2];
        let evanescent_offset = (4 + 1) * 2;
        data[evanescent_offset] = 0xEA;
        let grid = terrain::BlockGrid::from_level_layout(&data, 4, 4);

        assert_eq!(
            crate::level::evanescent_bullet_hitbox_scan_loc_EAE4(
                crate::level::EvanescentBulletHitboxScanInputLocEAE4 {
                    skip_scan_flag: false,
                    kid_hitbox_top: 0,
                    kid_hitbox_bottom: 15,
                    kid_hitbox_left: 0,
                    kid_hitbox_right: 15,
                    level_height_pixels: 64,
                    level_width_pixels: 64,
                },
                &grid,
            ),
            crate::level::EvanescentBulletHitboxScanLocEAE4::Scan {
                top_row: 0,
                bottom_row: 1,
                left_col: 0,
                right_col: 1,
                row_dbf_counter: 1,
                col_dbf_counter: 1,
                found_evanescent_block: true,
            },
            "ASM loc_EAE4 should clamp top/left after subtracting one pixel, include bottom/right after adding one pixel, and branch when `bclr #$F` finds block type `$A`"
        );
    }

    /// ASM loc_EAF8 (kid.asm:18866): `addq.w #1,d1` keeps the expanded bottom
    /// edge when it is still below `Level_height_pixels`; otherwise the ROM
    /// stores `Level_height_pixels - 1` in `d1`.
    #[test]
    #[allow(non_snake_case)]
    fn loc_EAF8_clamps_the_expanded_bottom_edge_to_level_height_minus_one() {
        assert_eq!(
            crate::level::evanescent_bullet_bottom_clamp_loc_EAF8(30, 64),
            crate::level::EvanescentBulletBottomClampLocEAF8 { bottom_px: 31 },
            "ASM loc_EAF8 should keep `Kid_hitbox_bottom + 1` when it is strictly below Level_height_pixels"
        );
        assert_eq!(
            crate::level::evanescent_bullet_bottom_clamp_loc_EAF8(63, 64),
            crate::level::EvanescentBulletBottomClampLocEAF8 { bottom_px: 63 },
            "ASM loc_EAF8 should clamp to Level_height_pixels - 1 once the expanded bottom reaches or exceeds the level height"
        );
    }

    /// ASM loc_EB0C (kid.asm:18874): the clamped top and bottom pixel edges
    /// become tile rows via `asr.w #4`; the bottom-minus-top result seeds the
    /// row DBF counter and the doubled top row indexes the row-pointer table.
    #[test]
    #[allow(non_snake_case)]
    fn loc_EB0C_converts_clamped_vertical_pixels_to_rows_and_row_pointer_offset() {
        assert_eq!(
            crate::level::evanescent_bullet_vertical_rows_loc_EB0C(0x001F, 0x0040),
            crate::level::EvanescentBulletVerticalRowsLocEB0C {
                top_row: 1,
                bottom_row: 4,
                row_dbf_counter: 3,
                first_row_pointer_table_byte_offset: 2,
            },
            "ASM loc_EB0C should divide both clamped pixel edges by 16, then double the top row before reading `$FFFF4A04(a0,d0.w)`"
        );
    }

    /// ASM loc_EB2A (kid.asm:18886): the right edge is expanded by one pixel,
    /// then clamped only when that expanded word is not strictly below
    /// `Level_width_pixels`.
    #[test]
    #[allow(non_snake_case)]
    fn loc_EB2A_clamps_the_expanded_right_edge_to_level_width_minus_one() {
        assert_eq!(
            crate::level::evanescent_bullet_right_clamp_loc_EB2A(30, 64),
            crate::level::EvanescentBulletRightClampLocEB2A { right_px: 31 },
            "ASM loc_EB2A should keep `Kid_hitbox_right + 1` when it is strictly below Level_width_pixels"
        );
        assert_eq!(
            crate::level::evanescent_bullet_right_clamp_loc_EB2A(63, 64),
            crate::level::EvanescentBulletRightClampLocEB2A { right_px: 63 },
            "ASM loc_EB2A should clamp to Level_width_pixels - 1 once the expanded right edge reaches or exceeds the level width"
        );
    }

    /// ASM loc_EB3E (kid.asm:18894): clamped horizontal pixel edges are shifted
    /// into tile columns, the inclusive width seeds `d2`, and the doubled left
    /// column advances `a0` into the first scanned cell.
    #[test]
    #[allow(non_snake_case)]
    fn loc_EB3E_converts_clamped_horizontal_pixels_to_columns_and_row_offset() {
        assert_eq!(
            crate::level::evanescent_bullet_horizontal_columns_loc_EB3E(0x001F, 0x0040),
            crate::level::EvanescentBulletHorizontalColumnsLocEB3E {
                left_col: 1,
                right_col: 4,
                col_dbf_counter: 3,
                first_cell_byte_offset: 2,
            },
            "ASM loc_EB3E should divide both clamped pixel edges by 16, subtract left from right for the DBF counter, and double left before adding it into a0"
        );
    }

    /// ASM loc_EB48 (kid.asm:18901): each outer-row iteration reloads `d3`
    /// from `d2` and `a1` from `a0`, so later rows rescan from the left column
    /// instead of continuing from the previous row's post-incremented pointer.
    #[test]
    #[allow(non_snake_case)]
    fn loc_EB48_resets_the_inner_scan_for_each_hitbox_row() {
        let mut data = vec![0; 4 * 3 * 2];
        let flagged_non_evanescent_offset = 2usize;
        data[flagged_non_evanescent_offset] = 0xE8;
        let evanescent_offset = ((4 + 1) * 2) as usize;
        data[evanescent_offset] = 0xEA;
        let grid = terrain::BlockGrid::from_level_layout(&data, 4, 3);
        let first_cell = grid.cell_at(1, 0);
        assert!(
            first_cell.has_block && first_cell.block_type != terrain::BlockType::Evanescent,
            "test fixture should put ASM loc_EB4C's block-flagged non-`$A00` cell before the real evanescent hit"
        );

        assert_eq!(
            crate::level::evanescent_bullet_scan_rows_loc_EB48(&grid, 0, 1, 1, 1),
            Some(crate::level::EvanescentBulletScanHitLocEB48 { col: 1, row: 1 }),
            "ASM loc_EB48 should restart the inner scan from the left column on the second row before loc_EB4C tests bit 15 and block type `$A`"
        );
    }

    /// ASM loc_EB62 (kid.asm:18913): both no-block cells and block-flagged
    /// non-`$A00` cells fall through to the scan-loop DBFs; only block-flagged
    /// `$A00` cells branch away to the evanescent trigger path.
    #[test]
    #[allow(non_snake_case)]
    fn loc_EB62_continues_the_scan_until_a_flagged_evanescent_cell() {
        assert_eq!(
            crate::level::evanescent_bullet_cell_scan_loc_EB62(0x6A00),
            crate::level::EvanescentBulletCellScanLocEB62::Continue,
            "ASM loc_EB62 should continue when `bclr #$F,d0` finds bit 15 already clear, even if the low type nibble is `$A`"
        );

        assert_eq!(
            crate::level::evanescent_bullet_cell_scan_loc_EB62(0xE800),
            crate::level::EvanescentBulletCellScanLocEB62::Continue,
            "ASM loc_EB62 should continue when the block flag is set but `andi.w #$F00,d0` is not `$A00`"
        );

        assert_eq!(
            crate::level::evanescent_bullet_cell_scan_loc_EB62(0xEA1D),
            crate::level::EvanescentBulletCellScanLocEB62::TriggerEvanescentBlock,
            "ASM loc_EB62 should not run for a block-flagged evanescent cell because loc_EB4C branches to loc_EB72 instead"
        );
    }

    /// ASM loc_EC52 (kid.asm:19111): only a zero age word at `$8(a0)` enters
    /// the bullet allocation loop; that path centres the stored block col/row
    /// in pixels and preserves `$6(a0)` as the direction bitfield.
    #[test]
    #[allow(non_snake_case)]
    fn loc_EC52_loads_only_zero_age_evanescent_objects() {
        assert_eq!(
            crate::level::evanescent_bullet_load_candidate_loc_EC52(0x04A6, 7, 12, 0b1010, 0,),
            Some(crate::level::EvanescentBulletLoadCandidateLocEC52 {
                layout_word_addr: 0x04A6,
                block_x_px: 120,
                block_y_px: 200,
                direction_bits: 0b1010,
            }),
            "ASM loc_EC52 should turn `$2/$4(a0)` block coords into centred pixel coords with `lsl #4; addq #8` before the direction loop"
        );

        assert_eq!(
            crate::level::evanescent_bullet_load_candidate_loc_EC52(0x04A6, 7, 12, 0b1010, 1,),
            None,
            "ASM loc_EC52 should branch to loc_ECA6 without loading bullets whenever `$8(a0)` is non-zero"
        );
    }

    /// ASM loc_EC76 (kid.asm:19127): direction bits are tested from 3 down to
    /// 0; each set bit consumes the current free shooter slot, pushes it to the
    /// active-list head, and initialises state `$FFFE`.
    #[test]
    #[allow(non_snake_case)]
    fn loc_EC76_loads_direction_bits_from_high_to_low_and_pushes_active_head() {
        let candidate = crate::level::EvanescentBulletLoadCandidateLocEC52 {
            layout_word_addr: 0x04A6,
            block_x_px: 120,
            block_y_px: 200,
            direction_bits: 0b1011,
        };
        let free_slots = [
            crate::level::LinkedObjectSlotInit {
                slot_addr: 0xFFFF_E9FA,
                next_slot_addr: 0xFFFF_EA06,
            },
            crate::level::LinkedObjectSlotInit {
                slot_addr: 0xFFFF_EA06,
                next_slot_addr: 0xFFFF_EA12,
            },
            crate::level::LinkedObjectSlotInit {
                slot_addr: 0xFFFF_EA12,
                next_slot_addr: 0,
            },
        ];

        assert_eq!(
            crate::level::evanescent_bullet_direction_load_loc_EC76(
                candidate,
                &free_slots,
                0xFFFF_E9FA,
                0xFFFF_EB00,
            ),
            Some(crate::level::EvanescentBulletDirectionLoadLocEC76 {
                next_free_shooter_object_slot_addr: 0,
                first_shooter_object_slot_addr: 0xFFFF_EA12,
                shooter_slots: vec![
                    crate::level::LinkedObjectSlotInit {
                        slot_addr: 0xFFFF_E9FA,
                        next_slot_addr: 0xFFFF_EB00,
                    },
                    crate::level::LinkedObjectSlotInit {
                        slot_addr: 0xFFFF_EA06,
                        next_slot_addr: 0xFFFF_E9FA,
                    },
                    crate::level::LinkedObjectSlotInit {
                        slot_addr: 0xFFFF_EA12,
                        next_slot_addr: 0xFFFF_EA06,
                    },
                ],
                loaded_slots: vec![
                    crate::level::LoadedShooterObjectLocEC76 {
                        slot_addr: 0xFFFF_E9FA,
                        layout_word_addr: 0x04A6,
                        block_x_px: 120,
                        block_y_px: 200,
                        direction: 3,
                        state: 0xFFFE,
                        next_active_slot_addr: 0xFFFF_EB00,
                    },
                    crate::level::LoadedShooterObjectLocEC76 {
                        slot_addr: 0xFFFF_EA06,
                        layout_word_addr: 0x04A6,
                        block_x_px: 120,
                        block_y_px: 200,
                        direction: 1,
                        state: 0xFFFE,
                        next_active_slot_addr: 0xFFFF_E9FA,
                    },
                    crate::level::LoadedShooterObjectLocEC76 {
                        slot_addr: 0xFFFF_EA12,
                        layout_word_addr: 0x04A6,
                        block_x_px: 120,
                        block_y_px: 200,
                        direction: 0,
                        state: 0xFFFE,
                        next_active_slot_addr: 0xFFFF_EA06,
                    },
                ],
                stopped_on_empty_free_list: false,
            }),
            "ASM loc_EC76 should visit bits 3, 1, then 0 for mask `%1011`, and each loaded slot should point at the previous active-list head"
        );
    }

    /// ASM loc_EC76 (kid.asm:19127): when a set direction bit finds
    /// `Addr_NextFreeShooterObjectSlot` zero, the ROM branches to `loc_ECA2`
    /// immediately instead of checking lower direction bits.
    #[test]
    #[allow(non_snake_case)]
    fn loc_EC76_stops_when_a_set_direction_finds_no_free_shooter_slot() {
        let candidate = crate::level::EvanescentBulletLoadCandidateLocEC52 {
            layout_word_addr: 0x04A6,
            block_x_px: 120,
            block_y_px: 200,
            direction_bits: 0b1011,
        };
        let free_slots = [crate::level::LinkedObjectSlotInit {
            slot_addr: 0xFFFF_E9FA,
            next_slot_addr: 0,
        }];

        assert_eq!(
            crate::level::evanescent_bullet_direction_load_loc_EC76(
                candidate,
                &free_slots,
                0xFFFF_E9FA,
                0,
            ),
            Some(crate::level::EvanescentBulletDirectionLoadLocEC76 {
                next_free_shooter_object_slot_addr: 0,
                first_shooter_object_slot_addr: 0xFFFF_E9FA,
                shooter_slots: vec![crate::level::LinkedObjectSlotInit {
                    slot_addr: 0xFFFF_E9FA,
                    next_slot_addr: 0,
                }],
                loaded_slots: vec![crate::level::LoadedShooterObjectLocEC76 {
                    slot_addr: 0xFFFF_E9FA,
                    layout_word_addr: 0x04A6,
                    block_x_px: 120,
                    block_y_px: 200,
                    direction: 3,
                    state: 0xFFFE,
                    next_active_slot_addr: 0,
                }],
                stopped_on_empty_free_list: true,
            }),
            "ASM loc_EC76 should load direction 3, then stop at direction 1 when the free-list head has become zero"
        );
    }

    /// ASM loc_EC9E (kid.asm:19143): every visited direction, including clear
    /// bits, reaches the `dbf` tail; the loop continues through directions
    /// 3, 2, 1, 0 and exits only after the counter wraps to `$FFFF`.
    #[test]
    #[allow(non_snake_case)]
    fn loc_EC9E_direction_loop_tail_exits_after_direction_zero() {
        assert_eq!(
            crate::level::evanescent_bullet_direction_loop_tail_loc_EC9E(3),
            crate::level::EvanescentBulletDirectionLoopTailLocEC9E {
                next_direction_counter: 2,
                loops_to_loc_ec76: true,
            },
            "ASM loc_EC9E should loop back to loc_EC76 after decrementing direction 3 to 2"
        );

        assert_eq!(
            crate::level::evanescent_bullet_direction_loop_tail_loc_EC9E(0),
            crate::level::EvanescentBulletDirectionLoopTailLocEC9E {
                next_direction_counter: 0xFFFF,
                loops_to_loc_ec76: false,
            },
            "ASM loc_EC9E should exit once DBF decrements direction 0 to `$FFFF`"
        );
    }

    /// ASM loc_ECC4 (kid.asm:19162): after the current evanescent slot ages
    /// out and is not the active-list head, the ROM follows predecessor links
    /// until `$A(a3)` equals the current `a0` slot.
    #[test]
    #[allow(non_snake_case)]
    fn loc_ECC4_finds_the_predecessor_of_the_aged_evanescent_slot() {
        let active_slots = [
            crate::level::LinkedObjectSlotInit {
                slot_addr: 0xFFFF_E90A,
                next_slot_addr: 0xFFFF_E91A,
            },
            crate::level::LinkedObjectSlotInit {
                slot_addr: 0xFFFF_E92A,
                next_slot_addr: 0,
            },
            crate::level::LinkedObjectSlotInit {
                slot_addr: 0xFFFF_E91A,
                next_slot_addr: 0xFFFF_E92A,
            },
        ];

        assert_eq!(
            crate::level::evanescent_bullet_recycle_predecessor_scan_loc_ECC4(
                &active_slots,
                0xFFFF_E92A,
            ),
            Some(crate::level::EvanescentBulletRecyclePredecessorLocECC4 {
                predecessor_slot_addr: 0xFFFF_E91A,
                scanned_links: 2,
            }),
            "ASM loc_ECC4 should follow `$A(a3)` links, not slice order, and branch to the splice block once the successor equals the aged slot"
        );

        assert_eq!(
            crate::level::evanescent_bullet_recycle_predecessor_scan_loc_ECC4(
                &active_slots,
                0xFFFF_E940,
            ),
            None,
            "ASM loc_ECC4 assumes a live active-list member; native returns None if the zero tail is reached without a predecessor"
        );
    }

    /// ASM loc_ECD2 (kid.asm:19170): the predecessor found in `a3` receives
    /// the aged evanescent object's saved successor link, unlinking the aged
    /// object before the shared free-list push.
    #[test]
    #[allow(non_snake_case)]
    fn loc_ECD2_splices_the_aged_evanescent_slot_out_of_the_active_list() {
        let active_slots = [
            crate::level::LinkedObjectSlotInit {
                slot_addr: 0xFFFF_E90A,
                next_slot_addr: 0xFFFF_E91A,
            },
            crate::level::LinkedObjectSlotInit {
                slot_addr: 0xFFFF_E91A,
                next_slot_addr: 0xFFFF_E92A,
            },
            crate::level::LinkedObjectSlotInit {
                slot_addr: 0xFFFF_E92A,
                next_slot_addr: 0xFFFF_E93A,
            },
            crate::level::LinkedObjectSlotInit {
                slot_addr: 0xFFFF_E93A,
                next_slot_addr: 0,
            },
        ];

        assert_eq!(
            crate::level::evanescent_bullet_recycle_splice_predecessor_loc_ECD2(
                &active_slots,
                0xFFFF_E91A,
                0xFFFF_E92A,
            ),
            Some(crate::level::EvanescentBulletRecycleSpliceLocECD2 {
                slots: vec![
                    crate::level::LinkedObjectSlotInit {
                        slot_addr: 0xFFFF_E90A,
                        next_slot_addr: 0xFFFF_E91A,
                    },
                    crate::level::LinkedObjectSlotInit {
                        slot_addr: 0xFFFF_E91A,
                        next_slot_addr: 0xFFFF_E93A,
                    },
                    crate::level::LinkedObjectSlotInit {
                        slot_addr: 0xFFFF_E92A,
                        next_slot_addr: 0xFFFF_E93A,
                    },
                    crate::level::LinkedObjectSlotInit {
                        slot_addr: 0xFFFF_E93A,
                        next_slot_addr: 0,
                    },
                ],
            }),
            "ASM loc_ECD2 should copy the target slot successor into the predecessor link without mutating the target until the later free-list push"
        );
    }

    /// ASM loc_ECD8 (kid.asm:19173): the aged evanescent slot is recycled by
    /// writing the old free-list head into `$A(a0)`, then making `a0` the new
    /// `Addr_NextFreeEvanescObjectSlot`; the saved successor in `d0` controls
    /// whether the active-list scan continues.
    #[test]
    #[allow(non_snake_case)]
    fn loc_ECD8_pushes_the_recycled_evanescent_slot_to_the_free_list() {
        let active_slots = [
            crate::level::LinkedObjectSlotInit {
                slot_addr: 0xFFFF_E90A,
                next_slot_addr: 0xFFFF_E91A,
            },
            crate::level::LinkedObjectSlotInit {
                slot_addr: 0xFFFF_E91A,
                next_slot_addr: 0xFFFF_E92A,
            },
            crate::level::LinkedObjectSlotInit {
                slot_addr: 0xFFFF_E92A,
                next_slot_addr: 0,
            },
        ];

        assert_eq!(
            crate::level::evanescent_bullet_recycle_free_list_push_loc_ECD8(
                &active_slots,
                0xFFFF_E91A,
                0xFFFF_E92A,
                0xFFFF_E980,
            ),
            Some(crate::level::EvanescentBulletRecycleFreeListPushLocECD8 {
                first_free_slot_addr: 0xFFFF_E91A,
                should_continue_active_scan: true,
                next_active_slot_to_process_addr: 0xFFFF_E92A,
                slots: vec![
                    crate::level::LinkedObjectSlotInit {
                        slot_addr: 0xFFFF_E90A,
                        next_slot_addr: 0xFFFF_E91A,
                    },
                    crate::level::LinkedObjectSlotInit {
                        slot_addr: 0xFFFF_E91A,
                        next_slot_addr: 0xFFFF_E980,
                    },
                    crate::level::LinkedObjectSlotInit {
                        slot_addr: 0xFFFF_E92A,
                        next_slot_addr: 0,
                    },
                ],
            }),
            "ASM loc_ECD8 should recycle `a0` by linking it to the previous free-list head and continue at loc_EC52 when saved d0 is non-zero"
        );

        assert_eq!(
            crate::level::evanescent_bullet_recycle_free_list_push_loc_ECD8(
                &active_slots,
                0xFFFF_E92A,
                0,
                0xFFFF_E980,
            )
            .map(|result| {
                (
                    result.first_free_slot_addr,
                    result.should_continue_active_scan,
                    result.next_active_slot_to_process_addr,
                )
            }),
            Some((0xFFFF_E92A, false, 0)),
            "ASM loc_ECD8 should fall through to Process_ShooterObjects when saved d0 is zero"
        );
    }

    /// ASM loc_ED04 (kid.asm:19208): the ROM indexes `unk_ECEC` with the
    /// pre-increment age word. Non-zero bytes branch to `loc_ED16`; zero bytes
    /// skip the evanescent action and follow `$A(a0)`.
    #[test]
    #[allow(non_snake_case)]
    fn loc_ED04_dispatches_from_the_evanescent_action_table() {
        assert_eq!(
            crate::level::evanescent_bullet_action_dispatch_loc_ED04(1, 0xFFFF_E91A),
            Some(
                crate::level::EvanescentBulletActionDispatchLocED04::ProcessAction {
                    action_byte: 0x81,
                }
            ),
            "ASM loc_ED04 should branch to loc_ED16 when `unk_ECEC[age]` is non-zero"
        );

        assert_eq!(
            crate::level::evanescent_bullet_action_dispatch_loc_ED04(13, 0),
            Some(
                crate::level::EvanescentBulletActionDispatchLocED04::ProcessAction {
                    action_byte: 0x83,
                }
            ),
            "ASM loc_ED04 should preserve the exact action byte; age 13 uses `$83`, enabling the later collision-overlay path"
        );

        assert_eq!(
            crate::level::evanescent_bullet_action_dispatch_loc_ED04(14, 0xFFFF_E91A),
            Some(
                crate::level::EvanescentBulletActionDispatchLocED04::ContinueActiveScan {
                    next_active_slot_addr: 0xFFFF_E91A,
                }
            ),
            "ASM loc_ED04 should continue at loc_EC52 when a zero action byte still has a next active slot"
        );

        assert_eq!(
            crate::level::evanescent_bullet_action_dispatch_loc_ED04(23, 0),
            Some(crate::level::EvanescentBulletActionDispatchLocED04::ProcessShooterObjects),
            "ASM loc_ED04 should fall through to Process_ShooterObjects when the zero action byte is also the active-list tail"
        );
    }

    /// ASM loc_ED16 (kid.asm:19216): negative action bytes stay in the fading
    /// evanescent path, emit a sprite only inside the inclusive camera window,
    /// and preserve bits 0/1 for the layout-update logic at `loc_ED52`.
    #[test]
    #[allow(non_snake_case)]
    fn loc_ED16_negative_actions_emit_visible_fade_sprites_and_layout_flags() {
        assert_eq!(
            crate::level::evanescent_bullet_action_loc_ED16(
                crate::level::EvanescentBulletActionInputLocED16 {
                    action_byte: 0x81,
                    block_col: 9,
                    block_row: 6,
                    min_visible_col: 1,
                    max_visible_col: 20,
                    min_visible_row: 2,
                    max_visible_row: 10,
                    camera_x_px: 0x0020,
                    camera_y_px: 0x0010,
                    current_sprite_link: 4,
                    loc_edbc_layout_offset: 0x0012,
                },
            ),
            crate::level::EvanescentBulletActionLocED16::NegativeAction {
                sprite: Some(crate::level::EvanescentBulletSpriteLocED16 {
                    y: 0x00D4,
                    link: 5,
                    tile_word: 0x8294,
                    x: 0x00F4,
                }),
                should_update_layout: true,
                use_collision_overlay: false,
            },
            "ASM loc_ED16 should write y/link/tile/x words for an in-window negative action before loc_ED52 consumes bit 0"
        );

        assert_eq!(
            crate::level::evanescent_bullet_action_loc_ED16(
                crate::level::EvanescentBulletActionInputLocED16 {
                    action_byte: 0x83,
                    block_col: 21,
                    block_row: 6,
                    min_visible_col: 1,
                    max_visible_col: 20,
                    min_visible_row: 2,
                    max_visible_row: 10,
                    camera_x_px: 0,
                    camera_y_px: 0,
                    current_sprite_link: 7,
                    loc_edbc_layout_offset: 0,
                },
            ),
            crate::level::EvanescentBulletActionLocED16::NegativeAction {
                sprite: None,
                should_update_layout: true,
                use_collision_overlay: true,
            },
            "ASM loc_ED16 should skip sprite output outside the inclusive block window while preserving bit 1 for the collision-overlay layout rewrite"
        );

        assert_eq!(
            crate::level::evanescent_bullet_action_loc_ED16(
                crate::level::EvanescentBulletActionInputLocED16 {
                    action_byte: 0x80,
                    block_col: 1,
                    block_row: 2,
                    min_visible_col: 1,
                    max_visible_col: 20,
                    min_visible_row: 2,
                    max_visible_row: 10,
                    camera_x_px: 0,
                    camera_y_px: 0,
                    current_sprite_link: 0,
                    loc_edbc_layout_offset: 0,
                },
            ),
            crate::level::EvanescentBulletActionLocED16::NegativeAction {
                sprite: Some(crate::level::EvanescentBulletSpriteLocED16 {
                    y: 0x00A4,
                    link: 1,
                    tile_word: 0x8294,
                    x: 0x0094,
                }),
                should_update_layout: false,
                use_collision_overlay: false,
            },
            "ASM loc_ED16 should treat the min visible column/row as in-window and let loc_EDB0 skip the layout rewrite when bit 0 is clear"
        );
    }

    /// ASM loc_ED16 (kid.asm:19216): `bpl.w loc_EDBC` sends positive action
